    async def create_acl(
        self,
        *,
        frontend_id: str,
        name: str,
        action: AclAction,
        index: int,
        zone: str | None = None,
        match_: AclMatch | None = None,
        description: str | None = None,
    ) -> Acl:
        """
        Create an ACL for a given frontend

        Create a new ACL for a given frontend. Each ACL must have a name, an action to
        perform (allow or deny), and a match rule (the action is carried out when the
        incoming traffic matches the rule).

        Args:
            zone: The zone you want to target
            frontend_id: Frontend ID to attach the ACL to.
            name: ACL name.
            action: Action to take when incoming traffic matches an ACL filter.
            match_: ACL match filter object. One of `ip_subnet`, `ips_edge_services` or
                `http_filter` & `http_filter_value` are required.
            index: Priority of this ACL (ACLs are applied in ascending order, 0 is the
                first ACL executed).
            description: ACL description.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/lb/v1/zones/{zone}/frontends/{frontend_id}/acls",
                zone=self._client.zone(zone),
                frontend_id=frontend_id,
            ),
            body={
                "name": name,
                "action": action,
                "match": match_,
                "index": index,
                "description": description,
            },
        )
        return Acl.model_validate(data)

