    async def create_lb(
        self,
        *,
        name: str,
        zone: str | None = None,
        organization_id: str | None = None,
        project_id: str | None = None,
        description: str | None = None,
        ip_id: str | None = None,
        assign_flexible_ip: bool | None = None,
        assign_flexible_ipv6: bool | None = None,
        ip_ids: list[str] | None = None,
        tags: list[str] | None = None,
        type_: str | None = None,
        ssl_compatibility_level: SSLCompatibilityLevel | None = None,
    ) -> Lb:
        """
        Create a Load Balancer

        Create a new Load Balancer. Note that the Load Balancer will be created without
        frontends or backends; these must be created separately via the dedicated
        endpoints.

        Args:
            zone: The zone you want to target
            organization_id: Scaleway Organization to create the Load Balancer in.
                Precisely one of project_id, organization_id can be set.
            project_id: Scaleway Project to create the Load Balancer in. Precisely one
                of project_id, organization_id can be set.
            name: Name for the Load Balancer.
            description: Description for the Load Balancer.
            ip_id: ID of an existing flexible IP address to attach to the Load Balancer.
            assign_flexible_ip: Defines whether to automatically assign a flexible
                public IP to the Load Balancer. Default value is `true` (assign).
            assign_flexible_ipv6: Defines whether to automatically assign a flexible
                public IPv6 to the Load Balancer. Default value is `false` (do not
                assign).
            ip_ids: List of IP IDs to attach to the Load Balancer.
            tags: List of tags for the Load Balancer.
            type_: Load Balancer commercial offer type. Use the Load Balancer types
                endpoint to retrieve a list of available offer types.
            ssl_compatibility_level: Determines the minimal SSL version which needs to
                be supported on the client side, in an SSL/TLS offloading context.
                Intermediate is suitable for general-purpose servers with a variety of
                clients, recommended for almost all systems (>= TLS1.2). Modern is
                suitable for services with clients that support TLS 1.3 and do not need
                backward compatibility (= TLS1.3). Old is compatible with a small number
                of very old clients and should be used only as a last resort (>=
                TLS1.0).
        """
        data = await self._client.request_json(
            "POST",
            self._client.path("/lb/v1/zones/{zone}/lbs", zone=self._client.zone(zone)),
            body={
                "name": name,
                "description": description,
                "ip_id": ip_id,
                "assign_flexible_ip": assign_flexible_ip,
                "assign_flexible_ipv6": assign_flexible_ipv6,
                "ip_ids": ip_ids,
                "tags": tags,
                "type": type_,
                "ssl_compatibility_level": ssl_compatibility_level,
                **self._client.owner(
                    project_id=project_id,
                    organization_id=organization_id,
                    keys=("project_id", "organization_id"),
                ),
            },
        )
        return Lb.model_validate(data)

