    async def create_backend(
        self,
        *,
        lb_id: str,
        name: str,
        forward_protocol: Protocol,
        forward_port: int,
        forward_port_algorithm: ForwardPortAlgorithm,
        sticky_sessions: StickySessionsType,
        health_check: HealthCheck,
        server_ip: list[str],
        zone: str | None = None,
        sticky_sessions_cookie_name: str | None = None,
        send_proxy_v2: bool | None = None,
        timeout_server: float | None = None,
        timeout_connect: float | None = None,
        timeout_tunnel: float | None = None,
        on_marked_down_action: OnMarkedDownAction | None = None,
        proxy_protocol: ProxyProtocol | None = None,
        failover_host: str | None = None,
        ssl_bridging: bool | None = None,
        ignore_ssl_server_verify: bool | None = None,
        redispatch_attempt_count: int | None = None,
        max_retries: int | None = None,
        max_connections: int | None = None,
        timeout_queue: str | None = None,
        host: str | None = None,
    ) -> Backend:
        """
        Create a backend for a given Load Balancer

        Create a new backend for a given Load Balancer, specifying its full
        configuration including protocol, port and forwarding algorithm.

        Args:
            zone: The zone you want to target
            lb_id: Load Balancer ID.
            name: Name for the backend.
            forward_protocol: Protocol to be used by the backend when forwarding traffic
                to backend servers.
            forward_port: Port to be used by the backend when forwarding traffic to
                backend servers.
            forward_port_algorithm: Load balancing algorithm to be used when determining
                which backend server to forward new traffic to.
            sticky_sessions: Defines whether to activate sticky sessions (binding a
                particular session to a particular backend server) and the method to use
                if so. None disables sticky sessions. Cookie-based uses an HTTP cookie
                TO stick a session to a backend server. Table-based uses the source
                (client) IP address to stick a session to a backend server.
            sticky_sessions_cookie_name: Cookie name for cookie-based sticky sessions.
            health_check: Object defining the health check to be carried out by the
                backend when checking the status and health of backend servers.
            server_ip: List of backend server IP addresses (IPv4 or IPv6) the backend
                should forward traffic to.
            send_proxy_v2: Deprecated in favor of proxy_protocol field.
            timeout_server: Maximum allowed time for a backend server to process a
                request. (in milliseconds)
            timeout_connect: Maximum allowed time for establishing a connection to a
                backend server. (in milliseconds)
            timeout_tunnel: Maximum allowed tunnel inactivity time after Websocket is
                established (takes precedence over client and server timeout). (in
                milliseconds)
            on_marked_down_action: Action to take when a backend server is marked as
                down.
            proxy_protocol: Protocol to use between the Load Balancer and backend
                servers. Allows the backend servers to be informed of the client's real
                IP address. The PROXY protocol must be supported by the backend servers'
                software.
            failover_host: Scaleway Object Storage bucket website to be served as
                failover if all backend servers are down, e.g. failover-
                website.s3-website.fr-par.scw.cloud.
            ssl_bridging: Defines whether to enable SSL bridging between the Load
                Balancer and backend servers.
            ignore_ssl_server_verify: Defines whether the server certificate
                verification should be ignored.
            redispatch_attempt_count: Whether to use another backend server on each
                attempt.
            max_retries: Number of retries when a backend server connection failed.
            max_connections: Maximum number of connections allowed per backend server.
            timeout_queue: Maximum time for a request to be left pending in queue when
                `max_connections` is reached. (in seconds)
            host: Host value to use when connecting to backend servers. When connecting
                to backend servers, use this value as the HTTP Host header or TLS SNI.
                This allows routing to specific services on the backend server that are
                configured to respond to particular hostnames.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/lb/v1/zones/{zone}/lbs/{lb_id}/backends",
                zone=self._client.zone(zone),
                lb_id=lb_id,
            ),
            body={
                "name": name,
                "forward_protocol": forward_protocol,
                "forward_port": forward_port,
                "forward_port_algorithm": forward_port_algorithm,
                "sticky_sessions": sticky_sessions,
                "sticky_sessions_cookie_name": sticky_sessions_cookie_name,
                "health_check": health_check,
                "server_ip": server_ip,
                "send_proxy_v2": send_proxy_v2,
                "timeout_server": timeout_server,
                "timeout_connect": timeout_connect,
                "timeout_tunnel": timeout_tunnel,
                "on_marked_down_action": on_marked_down_action,
                "proxy_protocol": proxy_protocol,
                "failover_host": failover_host,
                "ssl_bridging": ssl_bridging,
                "ignore_ssl_server_verify": ignore_ssl_server_verify,
                "redispatch_attempt_count": redispatch_attempt_count,
                "max_retries": max_retries,
                "max_connections": max_connections,
                "timeout_queue": timeout_queue,
                "host": host,
            },
        )
        return Backend.model_validate(data)

