    async def create_route(
        self,
        *,
        zone: str | None = None,
        frontend_id: str | None = None,
        backend_id: str | None = None,
        match_: RouteMatch | None = None,
    ) -> Route:
        """
        Create a route

        Create a new route on a given frontend. To configure a route, specify the
        backend to direct to if a certain condition is matched (based on the value of
        the SNI field or HTTP Host header).

        Args:
            zone: The zone you want to target
            frontend_id: ID of the source frontend to create the route on.
            backend_id: ID of the target backend for the route.
            match_: Object defining the match condition for a route to be applied. If an
                incoming client session matches the specified condition (i.e. it has a
                matching SNI value or HTTP Host header value), it will be passed to the
                target backend.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/lb/v1/zones/{zone}/routes", zone=self._client.zone(zone)
            ),
            body={
                "frontend_id": frontend_id,
                "backend_id": backend_id,
                "match": match_,
            },
        )
        return Route.model_validate(data)

