    async def create_subscriber(
        self,
        *,
        name: str,
        zone: str | None = None,
        email_config: SubscriberEmailConfig | None = None,
        webhook_config: SubscriberWebhookConfig | None = None,
        organization_id: str | None = None,
        project_id: str | None = None,
    ) -> Subscriber:
        """
        Create a subscriber

        Create a new subscriber, either with an email configuration or a webhook
        configuration, for a specified Scaleway Project.

        Args:
            zone: The zone you want to target
            name: Subscriber name.
            email_config: Email address configuration. Precisely one of email_config,
                webhook_config can be set.
            webhook_config: WebHook URI configuration. Precisely one of email_config,
                webhook_config can be set.
            organization_id: Organization ID to create the subscriber in. Precisely one
                of project_id, organization_id can be set.
            project_id: Project ID to create the subscriber in. Precisely one of
                project_id, organization_id can be set.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/lb/v1/zones/{zone}/subscribers", zone=self._client.zone(zone)
            ),
            body={
                "name": name,
                "email_config": email_config,
                "webhook_config": webhook_config,
                **self._client.owner(
                    project_id=project_id,
                    organization_id=organization_id,
                    keys=("project_id", "organization_id"),
                ),
            },
        )
        return Subscriber.model_validate(data)

